package test;

// Minimal stubs for compilation
class Position {
    int offset;
    public Position(int offset) { this.offset = offset; }
    public int getOffset() { return offset; }
}
interface ISourceViewer {}

class AbstractInlinedAnnotation {
    private Position position;
    private ISourceViewer viewer;
    protected InlinedAnnotationSupport support;

    public AbstractInlinedAnnotation(Position position, ISourceViewer viewer) {
        this.position = position;
        this.viewer = viewer;
    }

    public Position getPosition() { return position; }
    public ISourceViewer getViewer() { return viewer; }
}

class InlinedAnnotationSupport {
    public boolean isInVisibleLines(AbstractInlinedAnnotation annotation) { return true; } // Old signature
    public boolean isInVisibleLines(int offset) { return true; } // New signature
    public boolean anotherMethod(AbstractInlinedAnnotation annotation) { return false; }
}

public class ExampleClass extends AbstractInlinedAnnotation {
    public ExampleClass(Position position, ISourceViewer viewer) { super(position, viewer); }

    protected boolean checkVisibility() {
        // This should not be matched as the argument is not 'this'
        AbstractInlinedAnnotation otherAnn = new ExampleClass(new Position(10), null);
        return support.isInVisibleLines(otherAnn);
    }

    protected boolean otherMethod() {
        // This method call is different and should not be matched
        return support.anotherMethod(this);
    }

    // Another method that is fine as-is
    protected boolean checkOffsetDirectly() {
        return support.isInVisibleLines(getPosition().getOffset());
    }

    public static void main(String[] args) {
        Position p = new Position(0);
        ISourceViewer v = null;
        ExampleClass ex = new ExampleClass(p, v);
        ex.support = new InlinedAnnotationSupport();
        System.out.println(ex.checkVisibility());
    }
}
